use vstd::prelude::*;

verus! {

fn concat(a: &Vec<u64>, b: &Vec<u64>) -> (res: Vec<u64>)
    ensures
        // Length is the sum of lengths
        res@.len() == a@.len() + b@.len(),
        // Contents are a followed by b
        res@ == a@ + b@,
{
    let mut res = Vec::with_capacity(a.len() + b.len());
    res.extend_from_slice(a.as_slice());
    res.extend_from_slice(b.as_slice());

    // Help the verifier connect the two extends to the final sequence equality
    assert(res@.len() == a@.len() + b@.len());
    assert(res@ == a@ + b@);

    res
}

} // verus!

